__NUXT_JSONP__("/desarrollo-sostenible/eventos/alianza_latinoamerica_sostenible_abordara_experiencia_de_comunidades_durante_el_covid-19", (function(a,b,c,d,e){return {data:[{post:{slug:"alianza_latinoamerica_sostenible_abordara_experiencia_de_comunidades_durante_el_covid-19",title:"Alianza Latinoamérica Sostenible abordará experiencia de comunidades durante el Covid-19",date:"2023-10-03T22:18:50.379Z",img:"https:\u002F\u002Fucarecdn.com\u002F58aa885e-1257-432a-a7fc-e7361d0415da\u002F","img-alt":"Latinoamérica sostenible",autor:"Ethos",category:"desarrollo-sostenible",extracto:"En un contexto de crisis múltiple, para la alianza Latinoamérica Sostenible resulta fundamental conocer la experiencia de agrupaciones territoriales durante el Covid-19, extraer aprendizajes y fortalecer sus liderazgos para transitar hacia economías más sustentables. ",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"¿Qué estrategias permiten impulsar una transición justa y resiliente en las comunidades rurales de América Latina? En un contexto de crisis múltiple, para la alianza Latinoamérica Sostenible resulta fundamental conocer la experiencia de agrupaciones territoriales durante el Covid-19, extraer aprendizajes y fortalecer sus liderazgos para transitar hacia economías más sustentables. Por eso, junto a Rimisp - Centro Latinoamericano para el Desarrollo Rural y la Plataforma para una Reactivación Sostenible (PLARS), realizarán el seminario online “Transición justa y resiliencia en comunidades de América Latina”, el próximo jueves 12 de octubre a las 10:00 (México) \u002F11:00 (Colombia) \u002F 13:00 (Chile). "}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En la instancia participarán tres organizaciones comunitarias con enfoque en mujeres, comunidades indígenas y empleos verdes, que fueron parte del proyecto “Recuperación justa y resiliente de nuestras comunidades ante el COVID-19”, impulsado por la alianza Latinoamérica Sostenible durante 2022 y 2023. Así, Magdalena Morgan, gerenta del Comité de Agua Potable Rural de Hierro Viejo, Chile; Saúl Galeano, representante legal de Corcpresturg, Colombia; y Merced Gonzáles Cruz, facilitadora de la Agencia de Desarrollo Rural Sierra Norte, México, compartirán sus testimonios y las herramientas que pudieron desarrollar durante la ejecución de sus iniciativas. "}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Luego, para conversar sobre resiliencia, se dará paso a un panel de conversación integrado por Rodrigo Yañez, director Oficina Chile de RIMISP; Diego Saavedra, líder de proyectos DAR-PLARS; y Laure Delalande, directora de Inclusión y Desarrollo Sostenible de Ethos-Latinoamérica Sostenible. "}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Finalmente, se abordarán los desafíos de alcanzar una transición justa en las comunidades junto a Juliana Peña, Senior Officer para América Latina de NRGI-PLARS; Rodrigo Yañez, director Oficina Chile de RIMISP; y Rodrigo Guerrero, investigador de Medio Ambiente y Sustentabilidad de Espacio Público-Latinoamérica Sostenible"}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"La transmisión del seminario se realizará a través del canal de YouTube de Espacio Público. Si te interesa participar, "},{type:b,tag:"a",props:{href:"https:\u002F\u002Fforms.gle\u002FC4rJPzYgX93hN2Cm8",rel:["nofollow","noopener","noreferrer"],target:"_blank"},children:[{type:a,value:"regístrate aquí"}]},{type:a,value:"."}]}]},dir:"\u002Feventos",path:"\u002Feventos\u002Falianza_latinoamerica_sostenible_abordara_experiencia_de_comunidades_durante_el_covid-19",extension:".md",createdAt:e,updatedAt:e}}],fetch:{},mutations:[]}}("text","element","p","\n","2023-10-09T22:42:25.551Z")));